# ---------------- CERT-TBL: reproduce l205 table M_* / A_cell EXACTLY ------
def _asym(a, b):
    t = a + b
    return float((a - b) / t) if t else None


TBL_cert = 0
for J in JOINTS:
    cf, isLf = GROUPS[(J, "f")]
    ce, isLe = GROUPS[(J, "e")]
